CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS banks (id TEXT PRIMARY KEY, status TEXT NOT NULL DEFAULT 'initializing', customer_client INTEGER NOT NULL DEFAULT 0, customer_account INTEGER NOT NULL DEFAULT 0, recipient_client INTEGER NOT NULL DEFAULT 0, recipient_account INTEGER NOT NULL DEFAULT 0, employer_client INTEGER NOT NULL DEFAULT 0, employer_account INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, bank_id TEXT NOT NULL REFERENCES banks(id), role TEXT NOT NULL CHECK(role IN ('customer','officer','approver')), expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS applications (id TEXT PRIMARY KEY, bank_id TEXT NOT NULL REFERENCES banks(id), name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, address TEXT NOT NULL, employment TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'submitted', review_note TEXT, maker TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS application_bank ON applications(bank_id);
CREATE TABLE IF NOT EXISTS beneficiaries (id TEXT PRIMARY KEY, bank_id TEXT NOT NULL REFERENCES banks(id), name TEXT NOT NULL, account_id INTEGER NOT NULL, account_no TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(bank_id, account_id));
CREATE TABLE IF NOT EXISTS commands (id TEXT PRIMARY KEY, bank_id TEXT NOT NULL REFERENCES banks(id), key TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, amount_minor INTEGER NOT NULL, description TEXT NOT NULL, maker TEXT NOT NULL, approver TEXT, core_id INTEGER, account_id INTEGER NOT NULL, payload TEXT NOT NULL DEFAULT '{}', error TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(bank_id, key));
CREATE TABLE IF NOT EXISTS audit (id TEXT PRIMARY KEY, bank_id TEXT NOT NULL REFERENCES banks(id), actor TEXT NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, bank_id TEXT NOT NULL REFERENCES banks(id), name TEXT NOT NULL, kind TEXT NOT NULL, object_key TEXT NOT NULL, size INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS service_requests (id TEXT PRIMARY KEY, bank_id TEXT NOT NULL REFERENCES banks(id), kind TEXT NOT NULL, detail TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS commands_bank ON commands(bank_id, created_at);
CREATE INDEX IF NOT EXISTS audit_bank ON audit(bank_id, created_at);
CREATE INDEX IF NOT EXISTS documents_bank ON documents(bank_id);
